package media

import (
	"context"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"time"
)

// ErrNotFound means storage holds no file under the key (never stored, or deleted).
var ErrNotFound = errors.New("media: file not found")

// Storage holds media files by key. Keys are generated by this package (NewKey, ThumbKey).
type Storage interface {
	// Put stores r under key, replacing any file there. A reader sees the old file or the
	// whole new one, never a partial write.
	Put(ctx context.Context, key string, r io.Reader) error
	// Get opens the file under key, or returns ErrNotFound.
	Get(ctx context.Context, key string) (io.ReadCloser, error)
	// Delete removes the file under key. A missing file is not an error.
	Delete(ctx context.Context, key string) error
	// SignedURL is a URL that serves the file until expires without other credentials. It
	// may be relative to the server's base URL (starting with "/").
	SignedURL(ctx context.Context, key string, expires time.Time) (string, error)
}

// keyPattern matches the keys NewKey and ThumbKey generate.
var keyPattern = regexp.MustCompile(`^[0-9a-f]{32}(_t)?$`)

// ValidKey reports whether key has the form of a generated storage key.
func ValidKey(key string) bool { return keyPattern.MatchString(key) }

// ThumbKey is the storage key of the thumbnail for the file stored under key.
func ThumbKey(key string) string { return key + "_t" }

// Local stores files on disk under <dataDir>/media/aa/bb/<key>, where aa and bb are the key's
// first two pairs of hex digits. Its signed URLs point at this server's media file endpoint and
// carry an HMAC signature (Signer).
type Local struct {
	root   string
	prefix string // URL path the files are served under, e.g. /api/v1/media/files
	signer *Signer
}

// NewLocal returns local storage under dataDir. urlPrefix is the path of the endpoint that
// serves signed URLs. It touches no files until the first Put.
func NewLocal(dataDir, urlPrefix string, signer *Signer) *Local {
	return &Local{root: filepath.Join(dataDir, "media"), prefix: urlPrefix, signer: signer}
}

func (l *Local) path(key string) (string, error) {
	if !ValidKey(key) {
		return "", fmt.Errorf("media: invalid storage key %q", key)
	}
	return filepath.Join(l.root, key[0:2], key[2:4], key), nil
}

func (l *Local) Put(_ context.Context, key string, r io.Reader) (err error) {
	p, err := l.path(key)
	if err != nil {
		return err
	}
	dir := filepath.Dir(p)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("media: create dir: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".upload-*")
	if err != nil {
		return fmt.Errorf("media: create temp file: %w", err)
	}
	defer func() {
		if err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmp.Name())
		}
	}()
	if _, err = io.Copy(tmp, r); err != nil {
		return fmt.Errorf("media: write: %w", err)
	}
	if err = tmp.Sync(); err != nil {
		return fmt.Errorf("media: sync: %w", err)
	}
	if err = tmp.Close(); err != nil {
		return fmt.Errorf("media: close: %w", err)
	}
	if err = os.Rename(tmp.Name(), p); err != nil {
		return fmt.Errorf("media: rename: %w", err)
	}
	return nil
}

func (l *Local) Get(_ context.Context, key string) (io.ReadCloser, error) {
	p, err := l.path(key)
	if err != nil {
		return nil, err
	}
	f, err := os.Open(p) //nolint:gosec // p is built from a validated hex key under the media root
	if errors.Is(err, fs.ErrNotExist) {
		return nil, ErrNotFound
	}
	return f, err
}

func (l *Local) Delete(_ context.Context, key string) error {
	p, err := l.path(key)
	if err != nil {
		return err
	}
	if err := os.Remove(p); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	return nil
}

func (l *Local) SignedURL(ctx context.Context, key string, expires time.Time) (string, error) {
	if !ValidKey(key) {
		return "", fmt.Errorf("media: invalid storage key %q", key)
	}
	sig, err := l.signer.Sign(ctx, key, expires)
	if err != nil {
		return "", err
	}
	q := url.Values{"exp": {strconv.FormatInt(expires.Unix(), 10)}, "sig": {sig}}
	return l.prefix + "/" + key + "?" + q.Encode(), nil
}
